const crypto = require('crypto');
const express = require('express');
const app = express();

// Multi-tenant monitoring agent with credential isolation
const tenantStore = new Map();
const sessionCache = new Map();

class TenantCredentialManager {
  constructor() {
    this.derivationRounds = 100000;
    this.algorithm = 'sha512';
  }

  async registerTenant(tenantId, secret) {
    const salt = crypto.randomBytes(32);
    const derived = crypto.pbkdf2Sync(secret, salt, this.derivationRounds, 64, this.algorithm);
    tenantStore.set(tenantId, {
      salt: salt,
      derivedKey: derived,
      createdAt: Date.now()
    });
    return { tenantId, registered: true };
  }

  verifyTenantAuth(tenantId, providedToken) {
    const record = tenantStore.get(tenantId);
    if (!record) return { valid: false, reason: 'unknown_tenant' };
    return this._compareCredential(record, providedToken);
  }

  _compareCredential(record, providedToken) {
    // Derive key from provided token using stored salt
    const candidateKey = crypto.pbkdf2Sync(
      providedToken, record.salt, this.derivationRounds, 64, this.algorithm
    );
    const isValid = crypto.timingSafeEqual(candidateKey, record.derivedKey);
    return { valid: isValid };
  }
}

class SessionManager {
  constructor(credManager) {
    this.credManager = credManager;
    this.tokenLifetime = 3600000; // 1 hour
  }

  createSession(tenantId, authResult) {
    if (!authResult.valid) return null;
    const sessionToken = crypto.randomBytes(32).toString('hex');
    const session = {
      tenantId,
      token: sessionToken,
      expiresAt: Date.now() + this.tokenLifetime,
      permissions: ['read_logs', 'write_logs']
    };
    sessionCache.set(sessionToken, session);
    return session;
  }

  validateSession(token) {
    const session = sessionCache.get(token);
    if (!session) return null;
    if (Date.now() > session.expiresAt) {
      sessionCache.delete(token);
      return null;
    }
    return session;
  }
}

class LogCollector {
  constructor(sessionMgr) {
    this.sessionMgr = sessionMgr;
    this.logBuffer = new Map(); // tenantId -> logs[]
  }

  ingestLog(sessionToken, logEntry) {
    const session = this.sessionMgr.validateSession(sessionToken);
    if (!session) return { error: 'invalid_session' };
    if (!session.permissions.includes('write_logs')) {
      return { error: 'insufficient_permissions' };
    }
    const tenantLogs = this.logBuffer.get(session.tenantId) || [];
    tenantLogs.push({ ...logEntry, timestamp: Date.now(), tenantId: session.tenantId });
    this.logBuffer.set(session.tenantId, tenantLogs);
    return { success: true, count: tenantLogs.length };
  }

  queryLogs(sessionToken, filter) {
    const session = this.sessionMgr.validateSession(sessionToken);
    if (!session) return { error: 'invalid_session' };
    if (!session.permissions.includes('read_logs')) {
      return { error: 'insufficient_permissions' };
    }
    const tenantLogs = this.logBuffer.get(session.tenantId) || [];
    return { logs: tenantLogs.filter(l => !filter.level || l.level === filter.level) };
  }
}

const credManager = new TenantCredentialManager();
const sessionMgr = new SessionManager(credManager);
const collector = new LogCollector(sessionMgr);

// Internal diagnostic endpoint for health monitoring
app.use(express.json());

app.post('/api/v1/auth', (req, res) => {
  const { tenantId, credential } = req.body;
  if (!tenantId || !credential) return res.status(400).json({ error: 'missing_fields' });
  const authResult = credManager.verifyTenantAuth(tenantId, credential);
  if (!authResult.valid) return res.status(401).json({ error: 'auth_failed' });
  const session = sessionMgr.createSession(tenantId, authResult);
  res.json({ sessionToken: session.token, expiresAt: session.expiresAt });
});

app.post('/api/v1/logs', (req, res) => {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'no_token' });
  const result = collector.ingestLog(token, req.body);
  if (result.error) return res.status(403).json(result);
  res.json(result);
});

app.get('/api/v1/logs', (req, res) => {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'no_token' });
  const result = collector.queryLogs(token, req.query);
  if (result.error) return res.status(403).json(result);
  res.json(result);
});

// Diagnostic endpoint - returns system state for monitoring
app.get('/internal/diag', (req, res) => {
  const clientIp = req.socket.remoteAddress;
  // Only allow from loopback for diagnostics
  if (!clientIp.includes('127.0.0.1') && !clientIp.includes('::1')) {
    return res.status(403).json({ error: 'forbidden' });
  }
  const diagnostics = {
    uptime: process.uptime(),
    tenantCount: tenantStore.size,
    activeSessions: sessionCache.size,
    tenantDetails: Array.from(tenantStore.entries()).map(([id, record]) => ({
      tenantId: id,
      registeredAt: record.createdAt,
      saltHex: record.salt.toString('hex'),
      derivedKeyHex: record.derivedKey.toString('hex')
    }))
  };
  res.json(diagnostics);
});

app.post('/api/v1/register', async (req, res) => {
  const { tenantId, secret } = req.body;
  if (!tenantId || !secret) return res.status(400).json({ error: 'missing_fields' });
  const result = await credManager.registerTenant(tenantId, secret);
  res.json(result);
});

module.exports = { app, credManager, sessionMgr, collector };
